settings.liquid:
{%- assign v = product.selected_or_first_available_variant -%}
<style>
@import url('https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700;800;900&display=swap');
/* === Landing focus: hide nav + footer === */
.shopify-section-group-header-group,.shopify-section-group-footer-group,#reconvert-slot-announcement{display:none!important}
.swd *{box-sizing:border-box;margin:0;padding:0}
.swd{--bg:#f7f2e8;--ink:#17120e;--muted:#6b5f52;--copper:#B87533;--copper-d:#9c5f27;--line:rgba(23,18,14,.12);
font-family:'Outfit',system-ui,sans-serif;color:var(--ink);background:var(--bg);
margin-left:calc(50% - 50vw);margin-right:calc(50% - 50vw);overflow-x:clip;line-height:1.6;-webkit-font-smoothing:antialiased}
.swd img{display:block;max-width:100%}
.swd a{color:inherit;text-decoration:none}
.swd-wrap{max-width:1140px;margin:0 auto;padding:0 24px}
.swd-sec{padding:64px 0}
.swd h1,.swd h2{font-weight:800;letter-spacing:-.02em;line-height:1.08;color:var(--ink)}
.swd h1{font-size:clamp(30px,5vw,52px)}
.swd h2{font-size:clamp(26px,4vw,40px);margin-bottom:22px}
.swd p{font-size:17px;color:#2b231c;margin-bottom:14px}
.swd p b,.swd strong{color:var(--ink);font-weight:700}
.swd-kick{display:inline-block;font-size:12px;font-weight:700;letter-spacing:.18em;text-transform:uppercase;color:var(--copper);margin-bottom:14px}
/* HERO */
.swd-hero{padding:48px 0 56px}
.swd-hero-grid{display:grid;grid-template-columns:1fr 1fr;gap:44px;align-items:start}
.swd-gallery{display:grid;gap:14px}
.swd-gallery img{width:100%;border-radius:16px;border:1px solid var(--line);background:#fff}
.swd-buy{position:sticky;top:24px;background:#fff;border:1px solid var(--line);border-radius:20px;padding:30px;box-shadow:0 30px 60px -40px rgba(23,18,14,.4)}
.swd-buy .tag{display:inline-block;font-size:12px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--copper);border:1px solid var(--copper);border-radius:6px;padding:5px 10px;margin-bottom:16px}
.swd-buy .price{font-size:44px;font-weight:800;line-height:1}
.swd-buy .price s{font-size:24px;color:var(--muted);font-weight:500;margin-right:10px}
.swd-buy .sub{color:var(--muted);font-weight:600;margin:8px 0 18px}
.swd-list{list-style:none;margin:0 0 22px}
.swd-list li{position:relative;padding:8px 0 8px 28px;font-size:15.5px;border-bottom:1px solid var(--line)}
.swd-list li:last-child{border-bottom:none}
.swd-list li::before{content:"✓";position:absolute;left:0;top:8px;color:var(--copper);font-weight:800}
.swd-btn{display:block;width:100%;text-align:center;background:var(--copper);color:#fff;border:none;border-radius:10px;padding:18px;font-size:18px;font-weight:700;font-family:inherit;cursor:pointer;transition:background .2s}
.swd-btn:hover{background:var(--copper-d)}
.swd-form .shopify-payment-button{margin-top:12px}
.swd-form .shopify-payment-button__button{border-radius:10px!important;font-family:inherit!important}
.swd-trust{display:flex;flex-wrap:wrap;gap:14px;margin-top:18px;padding-top:18px;border-top:1px solid var(--line)}
.swd-trust span{font-size:13px;font-weight:600;color:var(--muted)}
.swd-trust b{color:var(--ink)}
/* PROBLEM */
.swd-prob p{max-width:760px}
/* BENEFITS (dark + copper) */
.swd-ben{background:var(--ink);color:#f7f2e8;border-radius:24px;padding:52px 40px}
.swd-ben h2{color:#fff;text-align:center;margin-bottom:34px}
.swd-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.swd-card{background:rgba(255,255,255,.04);border:1px solid rgba(184,117,51,.35);border-radius:16px;padding:26px}
.swd-card h3{font-size:19px;font-weight:700;margin-bottom:10px;color:#fff}
.swd-card p{font-size:14.5px;color:#cfc4b6}
.swd-bonus{margin-top:30px;background:rgba(184,117,51,.1);border:1px solid rgba(184,117,51,.4);border-radius:16px;padding:24px 28px}
.swd-bonus h3{color:var(--copper);font-size:16px;letter-spacing:.04em;text-transform:uppercase;margin-bottom:12px}
.swd-bonus ul{list-style:none}
.swd-bonus li{position:relative;padding:6px 0 6px 26px;color:#e8ddcd;font-size:15px}
.swd-bonus li::before{content:"🎁";position:absolute;left:0;top:5px;font-size:13px}
/* BIO */
.swd-bio-grid{display:grid;grid-template-columns:.85fr 1.15fr;gap:40px;align-items:center}
.swd-bio-grid img{border-radius:18px;border:1px solid var(--line)}
/* ACCORDION */
.swd-acc details{border:1px solid var(--line);border-radius:12px;margin-bottom:10px;background:#fff;overflow:hidden}
.swd-acc summary{cursor:pointer;list-style:none;padding:18px 22px;font-weight:700;font-size:16px;display:flex;justify-content:space-between;align-items:center}
.swd-acc summary::-webkit-details-marker{display:none}
.swd-acc summary::after{content:"+";color:var(--copper);font-size:22px;font-weight:700}
.swd-acc details[open] summary::after{content:"−"}
.swd-acc details>div{padding:0 22px 18px;color:#2b231c;font-size:15.5px}
/* CTA */
.swd-cta{background:var(--ink);color:#f7f2e8;border-radius:24px;padding:56px 40px;text-align:center}
.swd-cta h2{color:#fff}
.swd-cta p{color:#cfc4b6;max-width:680px;margin:0 auto 14px}
.swd-cta .swd-btn{display:inline-block;width:auto;padding:18px 44px;margin-top:18px}
.swd-center{text-align:center;max-width:760px;margin:0 auto}
@media(max-width:860px){.swd-hero-grid,.swd-bio-grid{grid-template-columns:1fr}.swd-cards{grid-template-columns:1fr}.swd-buy{position:static}}
</style>

<div class="swd">

  <!-- HERO + BUY -->
  <section class="swd-hero"><div class="swd-wrap"><div class="swd-hero-grid">
    <div>
      <span class="swd-kick">Ableton Live · Formation</span>
      <h1>{{ product.title }}</h1>
      <p style="margin-top:16px">Passe d'aspirant à producteur en franchissant enfin le cap : un workflow clair et efficace, de bonnes habitudes, sans devoir synthétiser des dizaines de tutoriels approximatifs. Objectif simple : te rendre à l'aise sur Ableton Live, une bonne fois pour toutes.</p>
      <div class="swd-gallery">
        {%- for media in product.media limit: 3 -%}
          <img src="{{ media | image_url: width: 900 }}" alt="{{ product.title }}" loading="lazy">
        {%- endfor -%}
      </div>
    </div>
    <aside class="swd-buy">
      <span class="tag">Accès à vie</span>
      <div class="price">{%- if v.compare_at_price > v.price -%}<s>{{ v.compare_at_price | money }}</s>{%- endif -%}{{ v.price | money }}</div>
      <div class="sub">Paiement unique · Accès à vie</div>
      <ul class="swd-list">
        <li>6 vidéos en HD · 2h21 de contenu</li>
        <li><b>Sample pack offert (+ de 200 samples)</b></li>
        <li>Défi : une prod en 5 sessions (PDF)</li>
        <li>Raccourcis clavier essentiels (PDF)</li>
        <li>Guide d'organisation des dossiers (PDF)</li>
        <li>Structure pédagogique claire</li>
        <li>Certificat de complétion</li>
      </ul>
      {%- form 'product', product, class: 'swd-form' -%}
        <input type="hidden" name="id" value="{{ v.id }}">
        <button type="submit" name="add" class="swd-btn">Je rejoins la formation — {{ v.price | money }}</button>
        {{ form | payment_button }}
      {%- endform -%}
      <div class="swd-trust"><span><b>✓</b> Garantie 30 jours</span><span><b>✓</b> Accès immédiat</span><span><b>✓</b> Satisfait ou remboursé</span></div>
    </aside>
  </div></div></section>

  <!-- PROBLEM -->
  <section class="swd-sec swd-prob"><div class="swd-wrap">
    <h2>Si tu débutes sur Ableton Live, tu fais sûrement face à l'un de ces problèmes :</h2>
    <p><b>Tu as peur de l'interface.</b> Elle peut paraître effrayante au premier abord : plein de sections, plein de boutons, tu ne sais pas par où commencer et l'idée de construire ton premier morceau te paraît totalement abstraite.</p>
    <p><b>Tu n'es pas sûr des habitudes que tu prends.</b> Naviguer dans la bibliothèque, utiliser le piano roll… Tu fais comme tu peux, mais sans vraie référence, tu doutes de ton workflow. Et tu as bien raison : les mauvaises habitudes s'installent vite, et sont bien plus dures à corriger après coup.</p>
    <p><b>Tu passes plus de temps sur YouTube que sur Ableton.</b> C'est la 18ème fois que tu tapes « Tuto Ableton », les infos se contredisent d'une source à l'autre et personne n'est là pour les trier. Résultat : tu n'as toujours pas commencé ta première boucle.</p>
    <p style="margin-top:22px"><b>Après plus de dix ans à produire de nombreux styles, voilà ce que je te propose : toutes les bonnes infos, au bon endroit, sans omission.</b></p>
    <p>J'ai passé des milliers d'heures sur Ableton. Après avoir formé des dizaines d'élèves et identifié leurs problématiques, j'ai conçu cette formation pour une chose : rendre la production musicale simple et accessible. Je l'ai pensée pour les débutants — que tu veuilles te mettre à la prod sérieusement ou juste te faire kiffer le dimanche.</p>
  </div></section>

  <!-- BENEFITS (dark + copper) -->
  <section class="swd-sec"><div class="swd-wrap"><div class="swd-ben">
    <h2>Ce que cette formation va t'apporter</h2>
    <div class="swd-cards">
      <div class="swd-card"><h3>✅ Maîtriser l'interface</h3><p>Une inspection détaillée de chaque section, en pédagogie pyramide, pour vulgariser l'usine à gaz qu'est Ableton et la rendre accessible.</p></div>
      <div class="swd-card"><h3>❌ Éviter les erreurs</h3><p>Je t'explique concrètement mes habitudes de production, déjà optimisées pour travailler le mieux et le plus rapidement possible.</p></div>
      <div class="swd-card"><h3>🎵 Produire régulièrement</h3><p>En prenant l'outil en main correctement, tu te donnes les moyens de prendre du plaisir en créant — et donc d'y revenir plus souvent.</p></div>
    </div>
    <div class="swd-bonus"><h3>Offerts dans la formation</h3><ul>
      <li>Un <b>sample pack de + de 200 samples</b> prêts à l'emploi</li>
      <li>Le <b>Défi : une prod en 5 sessions</b> (PDF)</li>
      <li>Les <b>raccourcis clavier essentiels</b> (PDF)</li>
      <li>Le <b>guide d'organisation des dossiers</b> (PDF)</li>
    </ul></div>
  </div></div></section>

  <!-- BIO -->
  <section class="swd-sec"><div class="swd-wrap"><div class="swd-bio-grid">
    <img src="{{ 'DSCF6092.png' | file_url }}" alt="Swander" loading="lazy" onerror="this.style.display='none'">
    <div>
      <h2>Pourquoi cette formation est faite pour toi</h2>
      <p>Je suis <b>Swander</b> — musicien, beatmaker et ingénieur du son depuis plus d'une décennie. J'ai débuté sur Ableton en 2013 et j'ai eu largement le temps d'en comprendre toutes les subtilités et d'optimiser mon workflow.</p>
      <p>J'enseigne Ableton depuis 2014 à des dizaines d'élèves, dont pas mal de débutants. J'ai pu décortiquer leurs besoins et synthétiser ça dans une formation claire, structurée et digeste.</p>
      <p>Tu y trouveras tout ce qu'il te faut pour bien commencer — ou consolider tes bases si tu as déjà bidouillé — sans avoir à recouper ça avec d'autres sources douteuses.</p>
    </div>
  </div></div></section>

  <!-- CURRICULUM -->
  <section class="swd-sec"><div class="swd-wrap">
    <h2 class="swd-center">Ce que tu retrouveras dans la formation</h2>
    <div class="swd-acc" style="margin-top:30px">
      <details open><summary>1 — Introduction et configuration</summary><div>Installation du logiciel, réglage des préférences, prise en main de la bibliothèque.</div></details>
      <details><summary>2 — Découverte de l'interface et de la bibliothèque</summary><div>Explication détaillée du fonctionnement de la bibliothèque, tour d'horizon des autres sections du logiciel.</div></details>
      <details><summary>3 — Création et gestion des pistes</summary><div>Création de pistes audio et MIDI, paramètres communs et particuliers, retours et master.</div></details>
      <details><summary>4 — Timeline et édition de clips</summary><div>Fonctionnement général, travail sur une piste audio, enregistrement et édition, introduction au piano roll.</div></details>
      <details><summary>5 — Automations et mapping</summary><div>Automation dans la Timeline et dans un clip MIDI, mapping et enregistrement d'automation.</div></details>
      <details><summary>6 — Sauvegarde et export</summary><div>Architecture du projet, partage, formats d'export, création de templates.</div></details>
    </div>
  </div></section>

  <!-- CTA -->
  <section class="swd-sec"><div class="swd-wrap"><div class="swd-cta">
    <h2>Franchis le cap et libère ton potentiel artistique</h2>
    <p>Adieu la peur de cliquer au mauvais endroit, exit l'angoisse de passer à côté d'une fonction essentielle ou de suivre une méthode bancale piochée au hasard. Tu prends en main ton logiciel, mais pas que : tu te rends maître de ta créativité et de ta passion.</p>
    <p>Sinon tu peux continuer à ouvrir ton logiciel 2 fois par mois et cliquer un peu au pif en espérant que ça donne quelque chose… Mais ça, <b>c'est toi qui vois.</b></p>
    <a href="#" class="swd-btn" onclick="window.scrollTo({top:0,behavior:'smooth'});return false;">Je rejoins la formation — {{ v.price | money }}</a>
  </div></div></section>

  <!-- FAQ -->
  <section class="swd-sec"><div class="swd-wrap">
    <h2 class="swd-center">Questions fréquentes</h2>
    <div class="swd-acc" style="margin-top:30px">
      <details><summary>Est-ce adapté aux vrais débutants ?</summary><div>Oui. Si tu ouvres Ableton et que tu ne sais même pas par où commencer, c'est exactement pour toi. On part de zéro.</div></details>
      <details><summary>J'ai déjà bidouillé, j'y apprends quoi ?</summary><div>Tu mets de la structure dans ce que tu sais, tu combles les manques et tu adoptes un vrai workflow optimisé. Tu repars sur de bonnes bases et tu gagnes du temps.</div></details>
      <details><summary>Est-ce adapté à mon style de musique ?</summary><div>Oui, totalement. Hip-hop, trap, techno, trance, EDM, drum &amp; bass, pop… la formation est universelle et orientée pratique.</div></details>
      <details><summary>J'ai peur que ce soit trop théorique.</summary><div>Chaque notion est expliquée avec des exemples concrets et des démonstrations. Tu apprends pour composer et progresser directement dans ton DAW.</div></details>
      <details><summary>Je n'ai pas beaucoup de temps.</summary><div>Tu suis la formation à ton rythme, en accès à vie. Chaque vidéo est claire et concise, pour avancer même avec 30 minutes par jour.</div></details>
      <details><summary>J'ai besoin de matériel spécifique ?</summary><div>Non. Un ordi, Ableton installé (n'importe quelle version), un casque ou des enceintes, et c'est parti.</div></details>
    </div>
  </div></section>

</div>
